{
 "summary": "The first theorem asserts that there exist two finitely generated, ICC, property-(T) countable groups Γ and Λ that are not isomorphic but have trace-preservingly *-isomorphic group von Neumann algebras. This is the two-group counterexample to Connes's conjecture. The second theorem is meant to formalize the infinite family of Theorem 1.2, but it quantifies universally (∀ Λ Γ) where the paper needs an existential. As written it claims every group and every sequence of groups has all these properties, which is false (take Λ trivial).",
 "glossary": [
  {"decl": "CountableDiscreteGroup", "line": 7, "plain": "A countable group bundled as a type with a group structure", "standard_concept": "countable discrete group", "matches_standard": "yes", "note": ""},
  {"decl": "IsICC", "line": 24, "plain": "G is infinite and every nonidentity conjugacy class is infinite", "standard_concept": "ICC group", "matches_standard": "yes", "note": ""},
  {"decl": "GroupsIsomorphic", "line": 27, "plain": "There is a group isomorphism G ≅ H", "standard_concept": "group isomorphism", "matches_standard": "yes", "note": ""},
  {"decl": "UnitaryRepresentation.HasAlmostInvariantUnitVectors", "line": 43, "plain": "For every finite K ⊆ G and every ε > 0 there is a unit vector ξ with ‖π(g)ξ − ξ‖ < ε for all g ∈ K", "standard_concept": "almost invariant vectors", "matches_standard": "yes", "note": ""},
  {"decl": "HasKazhdanPropertyT", "line": 49, "plain": "Every unitary representation on a complex Hilbert space in universe u with almost invariant unit vectors has a nonzero invariant vector", "standard_concept": "Kazhdan property (T)", "matches_standard": "yes", "note": "Only Hilbert spaces in universe 0 are quantified over; this is adequate for countable groups."},
  {"decl": "leftRegularRepresentation", "line": 106, "plain": "λ(g)f(h) = f(g⁻¹h) on ℓ²(G)", "standard_concept": "left regular representation", "matches_standard": "yes", "note": ""},
  {"decl": "groupVonNeumannAlgebra", "line": 143, "plain": "Bicommutant of {λ(g)} (together with adjoints) in B(ℓ²G)", "standard_concept": "group von Neumann algebra L(G)", "matches_standard": "yes", "note": ""},
  {"decl": "canonicalTrace", "line": 156, "plain": "τ(x) = ⟨δ_1, x δ_1⟩", "standard_concept": "canonical trace on L(G)", "matches_standard": "yes", "note": ""},
  {"decl": "IsNormalStarAlgEquiv", "line": 169, "plain": "The equivalence preserves projection suprema, where the order and suprema are defined algebraically inside the algebra", "standard_concept": "normal *-isomorphism", "matches_standard": "partly", "note": "This condition is automatic for any *-algebra isomorphism. That is harmless, since *-isomorphisms of von Neumann algebras are automatically normal."},
  {"decl": "TracialGroupFactorsIsomorphic", "line": 187, "plain": "There is a trace-preserving *-isomorphism L(G) ≅ L(H)", "standard_concept": "L(G) ≅ L(H)", "matches_standard": "yes", "note": "For II1 factors the trace condition is automatic. The Lean version is at least as strong as plain isomorphism."}
 ],
 "lean_claims": [
  {"theorem": "exists_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 199, "plain": "There exist countable groups Γ, Λ (in Type 0) that are finitely generated, ICC and have property (T), with L(Γ) ≅ L(Λ) trace-preservingly, and Γ ≇ Λ."},
  {"theorem": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 208, "plain": "For EVERY countable group Λ and EVERY sequence (Γ_n) of countable groups, all of the following hold: all are f.g., ICC and have property (T); L(Γ_n) ≅ L(Λ); L(Γ_m) ≅ L(Γ_n); Γ_m ≇ Γ_n for m ≠ n; and Λ ≇ Γ_n."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist finitely generated ICC property-(T) groups Λ, Γ_0, Γ_1, … that are pairwise nonisomorphic with L(Γ_n) ≅ L(Λ). Moreover, Γ_n contains a subgroup isomorphic to Γ_0 of index 2^{4n}, so the Γ_n are mutually commensurable."},
  {"ref": "Corollary 5.10", "plain": "The pair Λ, Γ_0 disproves Connes's rigidity conjecture."}
 ],
 "coverage": [
  {"paper_ref": "Corollary 5.10", "lean_theorem": "exists_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "relation": "equivalent", "why": "Existence of two nonisomorphic f.g. ICC property-(T) groups with isomorphic group factors."},
  {"paper_ref": "Theorem 1.2", "lean_theorem": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "relation": "different", "why": "A universal quantifier replaces the existential, so the Lean statement is false rather than the paper's claim."},
  {"paper_ref": "Theorem 1.2 (index 2^{4n} subgroup / commensurability)", "lean_theorem": null, "relation": "not_formalized", "why": "No commensurability or index statement appears in the Lean file."}
 ],
 "flags": [
  {"id": "F1", "category": "quantifier", "severity": "high", "decl": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 210, "paper_ref": "Theorem 1.2", "explanation": "The statement begins with ∀ (Λ) (Γ : ℕ → …) instead of ∃. It therefore asserts that every group is f.g., ICC and has property (T), and so on. This is false: the trivial group is not infinite, hence not ICC. The statement does not capture Theorem 1.2 and is unprovable.", "polarity": "lean stronger", "probe_idea": "Prove the negation: take Λ the trivial group (e.g. PUnit with a Countable instance) and derive ¬ IsICC Λ from ¬ Infinite PUnit."},
  {"id": "F2", "category": "coverage", "severity": "low", "decl": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 208, "paper_ref": "Theorem 1.2", "explanation": "The 'moreover' part is omitted: Γ_n has a subgroup ≅ Γ_0 of index 2^{4n}, so the Γ_n are mutually commensurable.", "polarity": "lean weaker", "probe_idea": null},
  {"id": "F3", "category": "definition-mismatch", "severity": "low", "decl": "IsNormalStarAlgEquiv", "line": 169, "paper_ref": null, "explanation": "The 'normality' condition uses suprema defined purely algebraically within the algebra. It is therefore preserved by any *-isomorphism and is vacuous rather than a genuine normality condition. This is harmless because *-isomorphisms of von Neumann algebras are automatically normal.", "polarity": "n/a", "probe_idea": "Prove that every A ≃⋆ₐ[ℂ] B satisfies IsNormalStarAlgEquiv."}
 ],
