  {"line": 71, "rule": "extended-arith", "verdict": "harmless", "why": "Proof-internal; the value is 2 > 0."},
  {"line": 74, "rule": "extended-arith", "verdict": "harmless", "why": "Proof-internal fact that (2:ℝ≥0∞).toReal > 0."},
  {"line": 76, "rule": "extended-arith", "verdict": "harmless", "why": "Proof-internal; the value is 2 > 0."},
  {"line": 97, "rule": "extended-arith", "verdict": "harmless", "why": "Rewriting the ℓ² norm with exponent 2; no junk value is involved."},
  {"line": 98, "rule": "extended-arith", "verdict": "harmless", "why": "Same as line 97."},
  {"line": 100, "rule": "extended-arith", "verdict": "harmless", "why": "Reindexing of a tsum by an equivalence; the exponent is 2."}
 ]
}
